{"qas": [
  {"question": "According to NIST SP 800-218A, what practices are recommended for tracking the provenance of both AI model components and training data?", "answer": "NIST SP 800-218A recommends tracking the provenance of AI model components, including libraries and frameworks, and also tracking the provenance of all training, testing, fine-tuning, and aligning data.", "evidence": [{"page": 21, "quote": "R1: Track the provenance of an AI model and its components and derivatives, including the training libraries, frameworks, and pipelines used to build the model."}, {"page": 23, "quote": "PW.3.2: Track the provenance, when known, of all training, testing, fine-tuning, and aligning data used for an AI model, and document which data do not have known provenance."}]},
  {"question": "What does NIST SP 800-218A recommend for verifying the integrity of acquired AI models and their components before use?", "answer": "NIST SP 800-218A recommends verifying the integrity, provenance, and security of acquired AI models and their components, and scanning and thoroughly testing them for vulnerabilities and malicious content before use.", "evidence": [{"page": 24, "quote": "R1: Verify the integrity, provenance, and security of an existing AI model or any other acquired AI components - including training, testing, fine-tuning, and aligning datasets;"}, {"page": 24, "quote": "R2: Scan and thoroughly test acquired AI models and their components for vulnerabilities and malicious content before use."}]},
  {"question": "In NIST SP 800-218A, what does 'SBOM' stand for as used in the context of provenance data collection?", "answer": "'SBOM' stands for 'software bill of materials' in the context of provenance data collection.", "evidence": [{"page": 21, "quote": "PS.3.2: Collect, safeguard, maintain, and share provenance data for all components of each software release (e.g., in a software bill of materials [SBOM], through Supply-chain Levels for Software Artifacts [SLSA]). [Modified from SSDF 1.1]"}]},
  {"question": "According to NIST SP 800-218A, what should be done if the provenance of training data is unknown?", "answer": "If the provenance of training data is unknown, it should still be tracked and documented as unknown, since tracking is beneficial for security even when provenance cannot be verified.", "evidence": [{"page": 23, "quote": "N1: Provenance verification is not possible in all cases because provenance is not always known. However, it is still beneficial for security purposes to track and verify provenance whenever possible, and to track when provenance is unknown."}]},
  {"question": "Which section in NIST SP 800-218A discusses the use of adversarial samples to improve AI model robustness, without using the phrase 'improve attack prevention'?", "answer": "Section PW.3.3 discusses including adversarial samples in training and testing data to enhance model robustness.", "evidence": [{"page": 23, "quote": "PW.3.3: Include adversarial samples in the training and testing data to improve attack prevention. [Not part of SSDF 1.1]"}]},
  {"question": "How does NIST SP 800-218A recommend handling AI model inputs and outputs to prevent unauthorized code execution?", "answer": "NIST SP 800-218A recommends encoding inputs and outputs to prevent the execution of unauthorized code.", "evidence": [{"page": 24, "quote": "R3: Encode inputs and outputs to prevent the execution of unauthorized code."}]}
]}
